$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$api = Decode ""
$component = Decode ""

$apiPath = Join-Path $root "app\api\provider\finance-audit\route.ts"
$componentPath = Join-Path $root "app\provider\payments\ProviderFinanceAudit.tsx"
$pagePath = Join-Path $root "app\provider\payments\page.tsx"
$financePath = Join-Path $root "app\api\provider\finance\route.ts"
$activityPath = Join-Path $root "app\api\provider\activity-summary\route.ts"

foreach ($path in @($pagePath, $financePath, $activityPath)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "13.03 : fichier requis introuvable : $path"
    }
}

$activity = [System.IO.File]::ReadAllText($activityPath)

if (-not $activity.Contains("KLYX_PROVIDER_GROUP_ACTIVITY_API_13_02")) {
    throw "13.03 : KLYX 13.02 introuvable."
}

New-Item -ItemType Directory -Force -Path (Split-Path -Parent $apiPath) | Out-Null

[System.IO.File]::WriteAllText($apiPath, $api, $utf8)
[System.IO.File]::WriteAllText($componentPath, $component, $utf8)

$page = [System.IO.File]::ReadAllText($pagePath)

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
Copy-Item -LiteralPath $pagePath -Destination ($pagePath + ".bak-13-03-" + $timestamp) -Force

if (-not $page.Contains("ProviderFinanceAudit")) {
    $importAnchor = 'import { createClient } from "@/lib/supabase/client";'

    if (-not $page.Contains($importAnchor)) {
        throw "13.03 : import createClient introuvable."
    }

    $newImport = $importAnchor + "`r`n" + 'import ProviderFinanceAudit from "./ProviderFinanceAudit";'

    $page = $page.Replace($importAnchor, $newImport)
}

if (-not $page.Contains("KLYX_GROUP_FINANCE_AUDIT_PAGE_13_03")) {
    $anchor = '            <section className="klyx-card mt-6 overflow-hidden">'

    if (-not $page.Contains($anchor)) {
        throw "13.03 : ancre historique financier introuvable."
    }

    $block = '            {/* KLYX_GROUP_FINANCE_AUDIT_PAGE_13_03 */}' + "`r`n" + '            <ProviderFinanceAudit />' + "`r`n`r`n"

    $page = $page.Replace($anchor, $block + $anchor)
}

[System.IO.File]::WriteAllText($pagePath, $page, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 13.03 APPLIQUE"
Write-Host "======================================"
Write-Host "Ledger groupe : AUDITE"
Write-Host "PaymentIntent duplique : DETECTE"
Write-Host "Refund duplique : DETECTE"
Write-Host "Allocations enfants : DISTINGUEES"
Write-Host "Montants modifies : NON"
Write-Host "Stripe modifie : NON"
Write-Host "Lecture seule : OUI"
Write-Host "======================================"
